def memoize(f): return lambda *x, cache={}: cache.get(x) or cache.setdefault(x, f(*x))

def edit_dist_top_bottom(a: str, b: str) -> int:

    @memoize
    def dp(i: int, j: int) -> int:
        '''edit distance btw a[i:] and b[j:]'''
        return min(
            dp(i+1, j) + 1,
            dp(i, j+1) + 1,
            dp(i+1,j+1) + (a[i] != b[j])
        ) if i < len(a) and j < len(b) else max(len(a)-i, len(b)-j)

    return dp(0, 0)

